# Calculate L_100
def lucas(n):
    if n == 0:
        return 2
    elif n == 1:
        return 1
    else:
        a, b = 2, 1
        for _ in range(2, n + 1):
            a, b = b, a + b
        return a

L_100 = lucas(100)
print(f"L_100 has {len(str(L_100))} digits.")
# Print a truncated version for verification
print(f"L_100 (start): {str(L_100)[:5]}...")
print(f"L_100 (end): ...{str(L_100)[-5:]}")

def fib(n):
    if n <= 1:
        return n
    a, b = 0, 1
    for _ in range(n - 1):
        a, b = b, a + b
    return b

differences = {}
for k in range(2, 11):
    differences[k] = fib(k)

print("F_2 to F_10:", differences)

